import re
import unicodedata

_CUES = {
    "sports": [
        (r"\b(?:nba|wnba|nfl|mlb|nhl|ncaa|fifa|uefa|atp|wta|olympics?|premier league|world cup|super bowl)\b", 5.0),
        (r"\b(?:basketball|baseball|softball|soccer|football|tennis|golf|hockey|cricket|rugby|boxing|wrestling|volleyball|badminton|formula one|f1 racing|motorsport|marathon)\b", 4.0),
        (r"\b(?:athlete|team|coach|player|captain|quarterback|pitcher|goalkeeper|striker|forward|defender|referee)\b", 2.5),
        (r"\b(?:match|tournament|championship|playoffs?|finals|league|season|race|grand prix|medal|record)\b", 2.0),
        (r"\b(?:score|scored|goal|goals|touchdown|home run|hat[- ]trick|penalty shootout|kickoff|kick-off)\b", 3.0),
        (r"\b(?:transfer|traded|drafted|signed|defeated|beat|beat(?:s|ing)?|wins?|won|draw(?:s|n)?)\b", 1.0),
        (r"\b(?:lakers|celtics|yankees|dodgers|cowboys|patriots|warriors|chiefs|real madrid|barcelona|manchester united|arsenal)\b", 3.5),
    ],
    "sci_tech": [
        (r"\b(?:technology|tech|software|hardware|computer|smartphone|iphone|ipad|android|operating system|microchip|chipmaker|semiconductor|processor|graphics card|artificial intelligence|machine learning|robotics|cybersecurity|virtual reality|cloud computing|video game|gaming console|social media|internet|website|app|application|database|algorithm|data center|5g|broadband|telecom(?:munications)?)\b", 3.5),
        (r"\b(?:scientists?|researchers?|scientific|research|experiment|discovery|study finds|clinical trial|medical research|vaccine|gene therapy|genome|cancer treatment|drug trial|biotech|biotechnology|laboratory|peer-reviewed)\b", 2.5),
        (r"\b(?:spacecraft|satellite|rocket|orbit|astronomers?|planetary|telescope|nasa|spacex|mars mission|space station)\b", 4.0),
        (r"\b(?:apple|google|alphabet|microsoft|meta|facebook|amazon|nvidia|intel|ibm|qualcomm|samsung|sony|oracle|openai|netflix|tesla|tiktok|huawei|amd|cisco|salesforce|adobe)\b", 4.5),
        (r"\b(?:smartwatch|electric vehicle|autonomous vehicle|self-driving|drone|3d printing|quantum computing|source code|software update|data breach|patent lawsuit|antitrust lawsuit)\b", 3.5),
        (r"\b(?:launches|unveils|debuts|releases|updates|develops|invents)\b", 0.8),
    ],
    "business": [
        (r"\b(?:stock market|share price|stock price|wall street|initial public offering|ipo|merger|acquisition|buyout|takeover|bankruptcy|goes bankrupt)\b", 4.0),
        (r"\b(?:stocks?|shares?|earnings|profits?|revenue|sales|dividend|quarterly results|fiscal year|investors?|investment|market value|valuation)\b", 2.7),
        (r"\b(?:economy|economic growth|gdp|inflation|recession|interest rates?|central bank|federal reserve|fed rate|unemployment|treasury bonds?|currency|exchange rate)\b", 3.0),
        (r"\b(?:oil|crude|natural gas|commodit(?:y|ies)|gold prices?|copper prices?|wheat prices?|energy prices?)\b", 2.7),
        (r"\b(?:trade deal|trade deficit|exports?|imports?|tariffs?|retail|retailer|airline|automaker|banking|banks?|insurance|real estate|shipping|manufacturing|supply chain)\b", 2.4),
        (r"\b(?:company|companies|firm|firms|corporation|ceo|chief executive|shareholders?|layoffs?|workers strike|union contract)\b", 1.5),
        (r"\b(?:merchants?|stores?|consumer spending|mortgage|loan|credit card|prices rise|price falls)\b", 1.8),
    ],
    "world": [
        (r"\b(?:election|electoral|presidential race|vote|voting|ballot|referendum|campaign trail)\b", 3.5),
        (r"\b(?:president|prime minister|parliament|congress|senate|government|minister|cabinet|ruling party|opposition party|legislature|politician|governor)\b", 2.5),
        (r"\b(?:war|invasion|airstrike|air strike|ceasefire|troops|military|armed forces|conflict|rebel|insurgent|terroris(?:m|t)|hostage|missile attack)\b", 4.0),
        (r"\b(?:diplomacy|diplomatic|foreign policy|peace talks|sanctions|border dispute|summit|treaty|refugees?|asylum seekers?)\b", 3.0),
        (r"\b(?:earthquake|hurricane|typhoon|tornado|floods?|wildfire|volcanic eruption|landslide|tsunami|disaster|evacuation)\b", 3.5),
        (r"\b(?:police|arrested|murder|killed|shooting|kidnapping|robbery|crime|criminal|prosecutors?|jury|verdict|sentenced)\b", 2.5),
        (r"\b(?:court|judge|lawsuit|legal ruling|lawmakers?|bill passes|law passed|constitutional)\b", 1.8),
        (r"\b(?:international|foreign|nationwide|country|countries|united nations|un security council)\b", 1.2),
    ],
}

def _collect_text(value):
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        preferred = ("text", "headline", "title", "content", "body", "description", "article")
        parts = []
        for key in preferred:
            if key in value:
                parts.extend(_collect_text(value[key]))
        if parts:
            return parts
        for item in value.values():
            parts.extend(_collect_text(item))
        return parts
    if isinstance(value, (list, tuple, set)):
        parts = []
        for item in value:
            parts.extend(_collect_text(item))
        return parts
    if value is None:
        return []
    return [str(value)]

def predict(state) -> dict:
    text = " ".join(_collect_text(state))
    text = unicodedata.normalize("NFKC", text).lower()
    scores = {category: 0.0 for category in _CUES}

    for category, cues in _CUES.items():
        for pattern, weight in cues:
            if re.search(pattern, text, re.IGNORECASE):
                scores[category] += weight

    # News about a technology company's financial results or legal disputes
    # is explicitly classified as science and technology.
    if re.search(
        r"\b(?:apple|google|alphabet|microsoft|meta|facebook|amazon|nvidia|intel|ibm|qualcomm|samsung|sony|oracle|openai|netflix|tesla|tiktok|huawei|amd|cisco|salesforce|adobe)\b",
        text,
        re.IGNORECASE,
    ):
        if re.search(r"\b(?:earnings|profits?|revenue|shares?|stocks?|lawsuit|sued|antitrust|settlement)\b", text):
            scores["sci_tech"] += 2.0

    # Give distinctive sports coverage precedence over incidental general-news terms.
    if scores["sports"] >= 5.0:
        scores["sports"] += 1.0

    order = ("sports", "sci_tech", "business", "world")
    answer = max(order, key=lambda category: scores[category])
    return {"answer": answer}

import re
import unicodedata


def _normalize(value):
    if not isinstance(value, str):
        value = str(value)
    value = unicodedata.normalize("NFKD", value.lower())
    value = "".join(ch for ch in value if not unicodedata.combining(ch))
    value = value.replace("’", "'")
    value = re.sub(r"\bu\.?\s*s\.?\b", "us", value)
    value = re.sub(r"\bu\.?\s*k\.?\b", "uk", value)
    return re.sub(r"[^a-z0-9]+", " ", value).strip()


def _has(text, pattern):
    return re.search(r"\b(?:" + pattern + r")\b", text) is not None


def _sum_groups(text, groups):
    return sum(weight for weight, pattern in groups if _has(text, pattern))


