    (8, r"software|operating system(?:s)?|windows (?:xp|vista|7|8|10|11)|linux|android|ios|macos|computer program(?:s)?|programming language(?:s)?|source code|open source|algorithm(?:s)?|artificial intelligence|machine learning|generative ai|chatbot(?:s)?|chatgpt"),
    (8, r"smartphone(?:s)?|iphone(?:s)?|ipad(?:s)?|ipod(?:s)?|macbook(?:s)?|laptop(?:s)?|computer(?:s)?|pc(?:s)?|microchip(?:s)?|semiconductor(?:s)?|processor(?:s)?|graphics card(?:s)?|gpu(?:s)?|cpu(?:s)?|server(?:s)?|data center(?:s)?"),
    (8, r"website(?:s)?|web site(?:s)?|internet|online platform(?:s)?|search engine(?:s)?|web browser(?:s)?|browser(?:s)?|social media|social network(?:s)?|e commerce|cloud computing|cybersecurity|cyberattack(?:s)?|ransomware|malware"),
    (7, r"mobile phone(?:s)?|cell phone(?:s)?|handset(?:s)?|tablet computer(?:s)?|smartwatch(?:es)?|wearable(?:s)?|digital camera(?:s)?|virtual reality|augmented reality|headset(?:s)?|touchscreen(?:s)?"),
