    (7, r"nasa|esa|spacecraft|space shuttle|space station|international space station|astronaut(?:s)?|cosmonaut(?:s)?|moon landing|mars rover|space exploration|space telescope|space mission(?:s)?|planet(?:s)?|galax(?:y|ies)|asteroid(?:s)?"),
    (7, r"scientist(?:s)?|scientific stud(?:y|ies)|researcher(?:s)?|research team(?:s)?|laborator(?:y|ies)|clinical trial(?:s)?|peer reviewed|experiment(?:s)?|study finds|studies find|new study"),
    (6, r"genom(?:e|es|ic|ics)|gene(?:s)?|dna|rna|stem cell(?:s)?|genetic(?:s|ally)?|biotechnology|biotech|molecul(?:e|es|ar)|quantum|particle physics|neuroscience|archaeolog(?:y|ical|ist|ists)|fossil(?:s)?"),
