    (9, r"stock market(?:s)?|share market(?:s)?|financial market(?:s)?|wall street|dow jones|s p 500|ftse|nikkei|nasdaq|stock exchange(?:s)?|bond market(?:s)?"),
    (7, r"stock(?:s)?|share(?:s)?|equities|equity market(?:s)?|bond(?:s)?|securit(?:y|ies)|investor(?:s)?|shareholder(?:s)?|trading|trader(?:s)?|ipo(?:s)?|initial public offering(?:s)?|market capitalization"),
