def predict(state) -> dict:
    text = _normalize(state)
    if not text:
        return {"answer": "world"}

    sports = _sum_groups(text, SPORT_GROUPS)
    tech = _sum_groups(text, TECH_GROUPS)
    business = _sum_groups(text, BUSINESS_GROUPS)
    world = _sum_groups(text, WORLD_GROUPS)

    tech_firm = _has(text, TECH_COMPANY)
    apple_firm = _has(text, r"apple|apple inc|apple computer")
    if apple_firm and not _has(text, r"apple(?:s)? (?:orchard|crop|harvest|juice|tree|fruit)|(?:orchard|crop|harvest|fruit) apple(?:s)?"):
        tech_firm = True
    amazon_forest = _has(text, r"amazon (?:rainforest|forest|river|basin|jungle)|(?:rainforest|forest|river) (?:of the )?amazon")
    if amazon_forest and not _has(text, r"amazon (?:com|web services|aws|prime)"):
        tech_firm = False
    if tech_firm:
        tech += 8

    finance_event = _has(
        text,
        r"earnings|revenue(?:s)?|profit(?:s)?|loss(?:es)?|share(?:s)?|stock(?:s)?|dividend(?:s)?|quarterly|financial result(?:s)?|investor(?:s)?|ipo(?:s)?|merger(?:s)?|acquisition(?:s)?|takeover(?:s)?|lawsuit(?:s)?|sue(?:s|d)?|antitrust",
    )
    broad_market = _has(
        text,
        r"stock market(?:s)?|financial market(?:s)?|wall street|dow jones|s p 500|ftse|nikkei|nasdaq|stock exchange(?:s)?|market wide|marketwide",
    )
    if tech_firm and finance_event:
        tech += 8 if not broad_market else 3
    if tech_firm and _has(text, r"launch(?:es|ed|ing)?|releas(?:e|es|ed|ing)|unveil(?:s|ed|ing)?|announc(?:e|es|ed|ing)|develop(?:s|ed|ing)?|updat(?:e|es|ed|ing)"):
        tech += 3

    research = _has(text, r"research|researcher(?:s)?|scientist(?:s)?|stud(?:y|ies)|experiment(?:s)?|trial(?:s)?|discover(?:y|ies|ed)|find(?:s|ing|ings)?|found")
    medical = _has(text, r"medic(?:al|ine)|health|disease(?:s)?|cancer|tumou?r(?:s)?|patient(?:s)?|doctor(?:s)?|drug(?:s)?|vaccine(?:s)?|therap(?:y|ies)|treatment(?:s)?|virus(?:es)?|genetic(?:s)?")
    if research and medical:
        tech += 8
    elif medical and _has(text, r"new drug(?:s)?|new vaccine(?:s)?|new treatment(?:s)?|drug approval|vaccine approval|fda approv(?:e|es|ed)|clinical trial(?:s)?"):
        tech += 6

    space_object = _has(text, r"space|satellite(?:s)?|rocket(?:s)?|spacecraft|astronaut(?:s)?|moon|mars|orbit(?:s|al|ing)?|nasa")
    if space_object and _has(text, r"launch(?:es|ed|ing)?|mission(?:s)?|explor(?:e|es|ed|ation)|land(?:s|ed|ing)?|orbit(?:s|ed|ing)?"):
        tech += 7
    if _has(text, r"missile(?:s)?|airstrike(?:s)?|bomb(?:s|ed|ing)?|attack(?:s|ed|ing)?") and _has(text, r"troop(?:s)?|military|war|rebel(?:s)?|civilian(?:s)?|kill(?:s|ed|ing)?|soldier(?:s)?"):
        world += 6

    athletic_anchor = _has(
        text,
        r"football|soccer|basketball|baseball|cricket|tennis|golf|hockey|rugby|boxing|athletics|swimming|cycling|skiing|gymnastics|marathon|olympic(?:s)?|world cup|super bowl|wimbledon|nba|nfl|mlb|nhl|fifa|uefa|ncaa|pga|ipl|playoff(?:s)?|champions league|quarterback|goalkeeper|touchdown|home run",
    )
    result = _has(text, SPORT_RESULTS)
    sport_context = _has(text, SPORT_CONTEXT)
    video_game = _has(text, VIDEO_GAME)
    if athletic_anchor and (result or sport_context):
        sports += 6
    elif result and sport_context and not video_game:
        sports += 5
    if _has(text, r"coach(?:es|ed)?|athlete(?:s)?|player(?:s)?|teammate(?:s)?") and (result or sport_context):
        sports += 3
    if _has(text, r"\d{1,2} \d{1,2}") and result and (athletic_anchor or sport_context):
        sports += 2
    if video_game:
        sports = max(0, sports - 5)

    corporate = _has(text, r"compan(?:y|ies)|corporat(?:ion|ions|e)|firm(?:s)?|business(?:es)?|retail(?:er|ers)?|airline(?:s)?|bank(?:s)?|manufacturer(?:s)?")
    if corporate and finance_event and not tech_firm:
        business += 4
    if broad_market:
        business += 5
    if _has(text, r"oil|crude|gasoline|commodity|commodities") and _has(text, r"pric(?:e|es)|cost(?:s)?|trading|market(?:s)?|barrel(?:s)?|opec"):
        business += 5
    if _has(text, r"airline(?:s)?|airway(?:s)?|aircraft|plane(?:s)?|flight(?:s)?") and _has(text, r"crash(?:es|ed)?|disaster|kill(?:s|ed)?|fatalit(?:y|ies)|emergency landing"):
        world += 9
    if _has(text, r"earthquake(?:s)?|hurricane(?:s)?|flood(?:s|ing)?|wildfire(?:s)?|tsunami(?:s)?") and _has(text, r"kill(?:s|ed)?|dead|evacuat(?:e|es|ed|ion)|destroy(?:s|ed)?|rescue(?:s|d)?"):
        world += 5

    # Political offices, court proceedings and ordinary games have meanings
    # outside their most common news categories.
    if tech_firm and _has(text, r"lawsuit(?:s)?|sue(?:s|d)?|suing|antitrust|patent(?:s)?|court(?:s)?|judge(?:s)?|trial(?:s)?"):
        tech += 7
    if corporate and _has(text, r"president(?:s)?|chief executive(?:s)?|ceo(?:s)?") and not _has(text, r"election(?:s)?|government|parliament|white house"):
        world = max(0, world - 5)
    if _has(text, r"game(?:s)?|match(?:es)?") and not athletic_anchor and not sport_context and not result:
        sports = max(0, sports - 3)
    if _has(text, r"world bank|international monetary fund|imf") and finance_event:
        business += 6

    scores = {
        "business": business,
        "sci_tech": tech,
        "sports": sports,
        "world": world,
    }
    highest = max(scores.values())
    if highest <= 0:
        return {"answer": "world"}

    leaders = [label for label, score in scores.items() if score == highest]
    if len(leaders) == 1:
        return {"answer": leaders[0]}

    # Resolve genuine evidence ties with the more specific subject, not the
    # iteration order of the labels.
    if "sports" in leaders and athletic_anchor and (result or sport_context):
        return {"answer": "sports"}
    if "sci_tech" in leaders and tech_firm and not broad_market:
        return {"answer": "sci_tech"}
    if "business" in leaders and broad_market:
        return {"answer": "business"}
    if "world" in leaders and _has(text, r"war|terroris(?:m|t|ts)|earthquake|tsunami|hurricane|election(?:s)?|murder(?:s|ed)?"):
        return {"answer": "world"}
    if "sci_tech" in leaders and (research or space_object or video_game):
        return {"answer": "sci_tech"}
    if "business" in leaders and finance_event:
        return {"answer": "business"}
    if "sports" in leaders and athletic_anchor:
        return {"answer": "sports"}
    return {"answer": "world" if "world" in leaders else sorted(leaders)[0]}

import re
import unicodedata


def _extract(state):
    if isinstance(state, str):
        return state
    if isinstance(state, (int, float)):
        return str(state)
    if isinstance(state, list):
        for item in reversed(state):
            if isinstance(item, dict) and item.get("role") in ("user", "customer"):
                return _extract(item.get("content", item.get("text", "")))
        return " ".join(_extract(item) for item in state)
    if isinstance(state, dict):
        for key in (
            "text", "message", "utterance", "query", "user_message",
            "customer_message", "input", "question", "content", "description",
        ):
            if key in state and state[key] is not None:
                return _extract(state[key])
        if "messages" in state:
            return _extract(state["messages"])
        if "state" in state:
            return _extract(state["state"])
        return " ".join(_extract(value) for value in state.values())
    return ""


def _normalise(value):
    value = unicodedata.normalize("NFKD", value.lower())
    value = "".join(c for c in value if not unicodedata.combining(c))
    value = re.sub(r"[^a-z0-9]+", " ", value)
    return " " + re.sub(r"\s+", " ", value).strip() + " "


def _has(text, *patterns):
    return any(re.search(pattern, text) is not None for pattern in patterns)


def _classify(text):
    card = _has(
        text, r"\bcard\b", r"\bplastic\b", r"\bvisa\b", r"\bmastercard\b",
        r"\bdebit\b", r"\bcredit card\b", r"\bcontactless\b",
    )
    virtual = _has(text, r"\bvirtual\b", r"\bdigital card\b", r"\be card\b")
    disposable = _has(text, r"\bdisposable\b", r"\bsingle use\b", r"\bone time (?:use )?card\b")
    cashout = _has(
        text, r"\bwithdraw", r"\batm\b", r"\bcash machine\b",
        r"\bcashpoint\b", r"\bautomated teller\b",
    )
    transfer = _has(
        text, r"\btransfer", r"\bwire\b", r"\bremitt", r"\biban\b",
        r"\bswift\b", r"\bsort code\b", r"\bbeneficiar", r"\brecipient\b",
        r"\bsepa\b", r"\bbacs\b", r"\bach payment\b", r"\bbank payment\b",
        r"\bsend money\b", r"\bsent money\b", r"\bsending money\b",
    )
    topup = _has(
        text, r"\btop up\b", r"\btopup\b", r"\btop ups\b", r"\btopups\b",
        r"\brecharg", r"\breload", r"\badd (?:money|funds|cash|balance)\b",
        r"\bput (?:money|funds|cash) (?:in|into|on|onto)\b",
        r"\bload (?:money|funds|cash|my account|the account)\b",
        r"\bfund (?:my|the|an) account\b", r"\bdeposit",
    )
    incoming = _has(
        text, r"\binto (?:my|the|this|our) account\b",
        r"\bto (?:my|the|this|our) account\b",
        r"\bincoming\b", r"\binbound\b", r"\breceiv",
        r"\bpaid (?:me|into my account)\b", r"\bsent (?:me|to me)\b",
        r"\bfrom (?:another|my|a|the) bank\b",
    )
    outbound = _has(
        text, r"\b(?:i|we) (?:have )?(?:sent|transferred|wired)\b",
        r"\bi (?:made|initiated|set up) (?:a |the )?transfer\b",
        r"\bto (?:someone|another person|my friend|the recipient|the beneficiary)\b",
        r"\bsend (?:money|funds|a transfer)\b",
        r"\bsent (?:money|funds|a transfer)\b",
        r"\bmy (?:recipient|beneficiary|payee)\b",
