    fee = _has(
        text, r"\bfees?\b", r"\bcommission\b", r"\bsurcharge\b",
        r"\bextra (?:charge|cost|money)\b", r"\bcharged (?:me|for|a fee)\b",
        r"\bcost (?:me|of|to)\b", r"\bdeducted\b",
