    )
    declined = _has(
        text, r"\bdeclin", r"\breject", r"\brefus", r"\bdenied\b",
        r"\bnot approved\b",
    )
    reversed_ = _has(
        text, r"\brevert", r"\brevers", r"\bbounced back\b",
        r"\breturned to (?:my|the) (?:account|card)\b",
        r"\bcharged back\b", r"\bchargeback\b",
    )
    failed = _has(
        text, r"\bfail", r"\bunsuccessful\b", r"\berror\b",
        r"\bnot (?:gone|going) through\b", r"\bwon t go through\b",
        r"\bdoesn t (?:go|work)\b", r"\bdidn t work\b",
        r"\bcannot (?:make|complete|do|process)\b",
        r"\bcan t (?:make|complete|do|process)\b",
        r"\bnot processed\b",
    )
    limits = _has(text, r"\blimit", r"\bmaximum\b", r"\bminimum\b", r"\bhow much\b", r"\bhow many\b")
    bank = _has(text, r"\bbank\b", r"\bwire\b", r"\biban\b", r"\bswift\b", r"\bsepa\b", r"\bsort code\b")
    cheque = _has(text, r"\bcheque", r"\bcheck deposit\b", r"\bdeposit (?:a |my )?check\b")
    cash_deposit = _has(
        text, r"\bcash deposit\b", r"\bdeposit(?:ing|ed)? cash\b",
        r"\bdeposit(?:ing|ed)? (?:some )?money (?:in person|at a branch)\b",
    )
    not_arrived = _has(
        text, r"\bnot (?:arriv|receiv|come|show|appear|turn up|deliver)",
        r"\bnever (?:arriv|receiv|came|showed|delivered)",
        r"\bhasn t (?:arriv|come|shown|turned)",
        r"\bhaven t (?:receiv|gotten|got)\b",
        r"\bstill (?:not here|waiting)\b", r"\bmissing\b",
        r"\bwhere (?:is|are) (?:my|the)\b",
    )
    payment = _has(
        text, r"\bpayment\b", r"\bpurchase\b", r"\btransaction\b",
        r"\bmerchant\b", r"\bshop\b", r"\bstore\b", r"\bcheckout\b",
        r"\bpaid\b", r"\bpaying\b", r"\bspent\b", r"\bcharge\b",
    )

    if _has(text, r"\b(?:apple pay|google pay|google wallet|apple wallet|gpay)\b"):
        return "apple_pay_or_google_pay"

    if _has(text, r"\b(?:phone|mobile|smartphone|device)\b") and _has(
        text, r"\b(?:lost|stolen|stole|misplaced|missing|robbed)\b"
    ):
        return "lost_or_stolen_phone"

    if _has(text, r"\b(?:close|delete|terminate|deactivate|shut down|cancel) (?:my |the |this )?account\b",
            r"\baccount (?:closure|termination|deletion)\b"):
