    if _has(text, r"\b(?:change|update|edit|correct|modify) (?:my |the )?(?:name|address|email|phone number|personal details|personal information|date of birth|profile)\b",
            r"\b(?:name|address|email|phone number|personal details|profile) (?:has changed|is wrong|needs updating)\b"):
        return "edit_personal_details"

    if _has(text, r"\b(?:forgot|forgotten|lost|reset|can t remember|do not remember) (?:my |the )?(?:passcode|password|app pin|login pin)\b"):
        return "passcode_forgotten"

    if _has(text, r"\b(?:source|origin|proof) of (?:my |the )?funds\b",
            r"\b(?:prove|verify|confirm|document) (?:where|how) (?:my |the )?money\b",
            r"\b(?:payslip|pay slip|proof of income|income documents)\b"):
        return "verify_source_of_funds"

    identity = _has(
        text, r"\b(?:identity|id verification|verify my id|verify my identity|verification of my id)\b",
        r"\b(?:passport|driving licen[cs]e|selfie|identification document)\b",
        r"\b(?:k y c|kyc)\b",
    )
    if identity:
        if _has(text, r"\bwhy\b", r"\bwhat for\b", r"\breason\b", r"\bnecessary\b",
                r"\bneed to\b", r"\brequired\b", r"\bhave to\b") and not _has(
                    text, r"\b(?:fail|rejected|unable|can t|cannot|error)\b"
                ):
            return "why_verify_identity"
        if _has(text, r"\b(?:fail|rejected|declined|unable|can t|cannot|won t|error|problem|stuck|unsuccessful)\b",
                r"\b(?:not|never) (?:verif|accept|work)\b"):
            return "unable_to_verify_identity"
        return "verify_my_identity"

    if _has(text, r"\b(?:direct debit|direct debits|autopay|standing debit)\b") and (
        unrecognised or _has(text, r"\b(?:unknown|not authorised|not authorized|didn t set up)\b")
    ):
        return "direct_debit_payment_not_recognised"

    if _has(text, r"\b(?:swallowed|eaten|ate|kept|retained|captured|trapped)\b") and (
        card or _has(text, r"\batm\b", r"\bcash machine\b")
    ):
        return "card_swallowed"

    if _has(text, r"\b(?:lost|stolen|stole|misplaced|missing|robbed)\b") and card:
        return "lost_or_stolen_card"

    if card and _has(
        text, r"\bcompromis", r"\bskim", r"\bclon", r"\bhack",
        r"\b(?:card|card details|card number) (?:information )?(?:leaked|exposed|copied)\b",
        r"\bsomeone (?:has|got|knows) my card (?:details|number)\b",
    ):
        return "compromised_card"

    if _has(text, r"\b(?:pin|p i n)\b") and not _has(text, r"\b(?:app pin|login pin)\b"):
        if _has(text, r"\b(?:blocked|locked|too many|incorrect attempts|wrong too many times|unblock)\b"):
            return "pin_blocked"
        if _has(text, r"\b(?:change|reset|update|new|forgot|forgotten|remember|retrieve|find out)\b"):
            return "change_pin"

    if disposable and limits:
        return "disposable_card_limits"

    if virtual:
        if _has(text, r"\b(?:not work|doesn t work|won t work|fail|declin|reject|problem|issue|can t use|cannot use|unable to use)\b"):
            return "virtual_card_not_working"
        if disposable:
            return "get_disposable_virtual_card"
        if _has(text, r"\b(?:get|obtain|create|generate|order|request|apply|make|set up|where|how)\b"):
            return "getting_virtual_card"

    if card and _has(text, r"\b(?:expir|renew|replacement for expiring|valid until|expiry date)\b"):
        return "card_about_to_expire"

    if card and _has(text, r"\b(?:activat|activation)\b"):
        return "activate_my_card"

    if _has(text, r"\b(?:contactless|tap to pay|tap and pay|nfc)\b") and _has(
        text, r"\b(?:not work|doesn t work|won t work|fail|declin|reject|problem|issue|can t|cannot|unable)\b"
    ):
        return "contactless_not_working"

    if card and _has(
        text, r"\b(?:link|unlink|connect|register|pair|associate) (?:my |the |a )?card\b",
        r"\b(?:add|attach) (?:my |the |a )?card to (?:my |the )?(?:account|app|profile)\b",
        r"\bcard (?:isn t|is not|won t) link\b",
    ):
        return "card_linking"

    if card and _has(text, r"\b(?:spare|extra|additional|second|backup|another) (?:physical )?card\b",
                    r"\b(?:card|one) (?:as a |for a )?(?:spare|backup)\b"):
        return "getting_spare_card"

    if card and _has(text, r"\b(?:deliver|arriv|shipping|shipment|ship|post|mail|courier|track my card)\b",
                     r"\bwhere (?:is|s) my card\b"):
        if _has(text, r"\b(?:how long|when will|when should|estimate|estimated|expected|delivery time|shipping time|time to arrive|how many days|how soon)\b") and not (
            not_arrived or _has(text, r"\blate\b", r"\boverdue\b")
        ):
            return "card_delivery_estimate"
        return "card_arrival"

    if card and _has(text, r"\b(?:physical|plastic|real|tangible) card\b",
                     r"\border (?:a |my |the )?card\b",
                     r"\b(?:get|request|apply for) (?:a |my |the )?new card\b"):
        if _has(text, r"\b(?:order|ordering|place an order|apply for|application to order)\b"):
            return "order_physical_card"
        return "get_physical_card"

    if _has(text, r"\b(?:visa|mastercard|master card)\b") and _has(
        text, r"\b(?:which|what|either|or|type|network|brand|issued|choose|offer|available|support)\b"
    ):
        return "visa_or_mastercard"

    if _has(text, r"\b(?:country|countries|region|residen|nationality|live in|living in|available in)\b") and (
        not card or _has(text, r"\b(?:open|register|sign up|account|service|supported)\b")
    ):
        return "country_support"

    if _has(text, r"\b(?:which|what|supported|available|accept)\b") and _has(
        text, r"\b(?:currencies|currency|fiat)\b"
    ) and _has(text, r"\b(?:account|hold|balance|wallet|fiat|supported currencies)\b") and not (
        topup or card or rate
    ):
        return "fiat_currency_support"

    if _has(text, r"\b(?:which|what|supported|accept|use)\b") and (
        _has(text, r"\b(?:cards and currencies|cards or currencies)\b")
        or (topup and _has(text, r"\b(?:cards|currencies|currency|visa|mastercard|debit card|credit card)\b"))
    ) and not _has(text, r"\b(?:fee|charge|declin|fail|pending|limit)\b"):
        return "supported_cards_and_currencies"

    if _has(text, r"\b(?:exchange|convert|swap|change)\b") and fx and _has(
        text, r"\b(?:in the app|on the app|using the app|through the app|within the app|in my account|between my accounts|how do i|how can i)\b"
    ) and not (rate or fee):
        return "exchange_via_app"

    if cashout:
        if unrecognised:
            return "cash_withdrawal_not_recognised"
        if rate and _has(text, r"\b(?:wrong|incorrect|bad|different|unexpected|unfair|poor|not the|why)\b"):
            return "wrong_exchange_rate_for_cash_withdrawal"
        if _has(
            text, r"\b(?:wrong|incorrect|less|short|partial|different|no) (?:amount|cash|money)\b",
            r"\b(?:didn t|did not|never|not) (?:get|receive|dispense|come out) (?:any |the |my )?(?:cash|money|full amount)\b",
            r"\b(?:machine|atm) (?:gave|dispensed) (?:me )?(?:less|nothing|the wrong)\b",
            r"\b(?:charged|debited) (?:but|without) (?:receiving|getting|dispensing)\b",
        ):
            return "wrong_amount_of_cash_received"
        if declined:
            return "declined_cash_withdrawal"
        if pending:
            return "pending_cash_withdrawal"
        if fee or _has(text, r"\b(?:charged|cost|price) (?:to |for )?(?:withdraw|take out cash)\b"):
            return "cash_withdrawal_charge"
        if _has(text, r"\b(?:where|which|what|can i|how do i|able to|supported|work|use)\b"):
            return "atm_support"
        return "atm_support"

    if _has(text, r"\b(?:refund|money back|reimburse)\b"):
        if _has(
            text, r"\b(?:not|never|hasn t|haven t|still waiting|missing|where is|where s)\b",
            r"\b(?:when|how long) (?:will|does|until).{0,35}(?:arrive|show|receive)\b",
        ) and (_has(text, r"\b(?:issued|processed|approved|promised|sent|given|due|expected)\b")
               or not_arrived or _has(text, r"\b(?:not showing|not in my account|still waiting|where is my refund)\b")):
            return "refund_not_showing_up"
        if _has(text, r"\b(?:ask|request|get|obtain|claim|want|need|how|can i|possible|entitled)\b"):
            return "request_refund"
        if not_arrived:
            return "refund_not_showing_up"

    if _has(text, r"\b(?:twice|two times|double|duplicate|duplicated|multiple times|more than once)\b") and (
        payment or topup or transfer or cashout or _has(text, r"\bdebited\b")
    ):
        return "transaction_charged_twice"

    if topup and (
        _has(text, r"\b(?:cash|cheque)\b") or cheque
    ) and not cashout:
        if _has(text, r"\b(?:not showing|not reflected|balance|not credited|missing|not updated)\b") and (
            not_arrived or _has(text, r"\b(?:not showing|not reflected|not credited|not updated)\b")
