            return "balance_not_updated_after_cheque_or_cash_deposit"
        return "top_up_by_cash_or_cheque"

    if topup:
        if _has(text, r"\b(?:automatic|automatically|auto top|recurring|regularly|scheduled|repeat|when my balance is low)\b"):
