            return "top_up_by_card_charge"
        if cheque or cash_deposit:
            return "top_up_by_cash_or_cheque"
        if bank or transfer:
            if _has(text, r"\b(?:not showing|not reflected|not credited|not updated|missing from my balance)\b") or (
                not_arrived and _has(text, r"\bbalance\b", r"\baccount\b")
            ):
                return "balance_not_updated_after_bank_transfer"
            return "transfer_into_account"
        if card or _has(text, r"\b(?:debit|credit) card\b"):
            return "topping_up_by_card"
        return "topping_up_by_card"

    if transfer or (bank and incoming):
        if _has(text, r"\b(?:cancel|stop|recall|undo|revoke|take back)\b") and not reversed_:
            return "cancel_transfer"
        if _has(text, r"\b(?:beneficiary|recipient|payee)\b") and _has(
            text, r"\b(?:not allowed|isn t allowed|cannot|can t|not permitted|prohibited|restricted|blocked|invalid)\b"
        ):
            return "beneficiary_not_allowed"
        if fee:
            if incoming or _has(text, r"\b(?:deposit|top up)\b"):
                return "top_up_by_bank_transfer_charge"
            return "transfer_fee_charged"
        if declined:
            return "declined_transfer"
        if failed:
            return "failed_transfer"
        if pending:
            return "pending_transfer"
        if _has(text, r"\b(?:recipient|beneficiary|payee|person i sent|person i paid|other person|other bank account)\b") and (
            not_arrived or _has(text, r"\b(?:hasn t got|hasn t received|still waiting|not credited)\b")
        ):
            return "transfer_not_received_by_recipient"
        if (incoming or _has(text, r"\b(?:my balance|account balance|in my account)\b")) and _has(
            text, r"\b(?:not showing|not reflected|not credited|not updated|missing|not appeared|doesn t show|does not show)\b"
        ):
            return "balance_not_updated_after_bank_transfer"
        if incoming and not outbound:
            if _has(text, r"\b(?:hasn t arrived|haven t received|not arrived|still waiting)\b") and _has(
                text, r"\bbalance\b", r"\bin my account\b"
            ):
                return "balance_not_updated_after_bank_transfer"
            if _has(text, r"\b(?:how long|when|time|days|wait)\b"):
                return "transfer_timing"
            if _has(text, r"\b(?:receive money|receiving money|receive payments|get paid|someone send|people send)\b") and not bank:
                return "receiving_money"
            return "transfer_into_account"
        if not_arrived and _has(text, r"\b(?:recipient|beneficiary|payee|person)\b"):
            return "transfer_not_received_by_recipient"
        if _has(text, r"\b(?:how long|when will|how soon|time|days|hours|speed|duration|eta)\b"):
            return "transfer_timing"
        if _has(text, r"\b(?:receive|receiving|get paid|sent to me)\b"):
            return "receiving_money"
        return "transfer_timing"

    if _has(text, r"\b(?:receive|receiving|get paid|send me money)\b") and _has(
        text, r"\b(?:money|funds|payment|paid)\b"
    ):
        return "receiving_money"

    if card or payment:
        if unrecognised:
            return "card_payment_not_recognised"
        if reversed_ and payment:
            return "reverted_card_payment"
        if rate and payment and _has(
            text, r"\b(?:wrong|incorrect|bad|different|unexpected|unfair|poor|not the|why)\b"
        ):
            return "card_payment_wrong_exchange_rate"
        if fee and payment:
            return "card_payment_fee_charged"
        if pending and payment:
            return "pending_card_payment"
        if declined and payment:
            return "declined_card_payment"
        if _has(text, r"\b(?:extra|additional|unexplained|unexpected|strange) (?:charge|debit|transaction)\b",
                r"\bcharge (?:on|in) (?:my|the) statement\b"):
            return "extra_charge_on_statement"
        if _has(text, r"\b(?:accept|accepted|acceptance|use|usable|work) (?:my |the |this )?card\b",
                r"\bcard (?:accepted|usable)\b",
                r"\b(?:where|which shops|which stores|which places).{0,30}(?:card|accept)\b") and not (
            failed or declined
        ):
            return "card_acceptance"
        if _has(text, r"\b(?:not work|doesn t work|won t work|broken|damaged|faulty|can t use|cannot use|problem with my card)\b"):
            if payment:
                return "declined_card_payment"
            return "card_not_working"
        if declined:
            return "declined_card_payment"
        if payment:
            return "card_payment_not_recognised" if unrecognised else "card_acceptance"
        return "card_not_working"

    if fx:
        if fee:
            return "exchange_charge"
        if _has(text, r"\b(?:which|what|supported|available)\b") and _has(
            text, r"\b(?:currency|currencies|fiat)\b"
        ) and not rate:
            return "fiat_currency_support"
        if _has(text, r"\b(?:how|where|can i|want to)\b") and _has(
            text, r"\b(?:exchange|convert|swap)\b"
        ) and not rate:
            return "exchange_via_app"
        return "exchange_rate"

    if _has(text, r"\b(?:statement|account activity)\b") and _has(
        text, r"\b(?:extra|additional|unexplained|unexpected|unknown) (?:charge|debit|transaction)\b"
    ):
        return "extra_charge_on_statement"

    if _has(text, r"\b(?:balance|account)\b") and _has(
        text, r"\b(?:deposit|cheque|cash)\b"
    ) and _has(text, r"\b(?:missing|not updated|not showing|not credited)\b"):
        return "balance_not_updated_after_cheque_or_cash_deposit"

    if _has(text, r"\b(?:atm|cash machine)\b"):
        return "atm_support"
    if _has(text, r"\b(?:fee|charge|commission)\b"):
        return "extra_charge_on_statement"
    return "card_not_working"


def predict(state) -> dict:
    text = _normalise(_extract(state))
    return {"answer": _classify(text)}
